"""Small file helpers."""
import os


def list_files(directory):
    return sorted(n for n in os.listdir(directory) if os.path.isfile(os.path.join(directory, n)))


def remove_older_than(directory, days, now=None):
    """Delete regular files older than `days`; return the removed names."""
    import time
    cutoff = (time.time() if now is None else now) - days * 86400
    removed = []
    for name in list_files(directory):
        path = os.path.join(directory, name)
        if not os.path.islink(path) and os.path.getmtime(path) < cutoff:
            os.remove(path)
            removed.append(name)
    return removed
